-- Semis de données de test : 100 tablées dans 20 villes, avec leurs hôtes,
-- invités, apports et la liste d'ingrédients proposée par l'hôte.
-- Rejouable : les lignes précédentes (emails en seed.*@labonnetablee.test) sont purgées.
-- Application : npx wrangler d1 execute labonnetablee-db --local --file=seed/menus.sql

DELETE FROM contributions WHERE participationId IN (
  SELECT p.id FROM participations p
  WHERE p.tableId IN (SELECT t.id FROM tables t WHERE t.hostId IN (SELECT id FROM users WHERE email LIKE 'seed.%@labonnetablee.test'))
     OR p.userId IN (SELECT id FROM users WHERE email LIKE 'seed.%@labonnetablee.test')
);
DELETE FROM participations
 WHERE tableId IN (SELECT id FROM tables WHERE hostId IN (SELECT id FROM users WHERE email LIKE 'seed.%@labonnetablee.test'))
    OR userId IN (SELECT id FROM users WHERE email LIKE 'seed.%@labonnetablee.test');
DELETE FROM tables WHERE hostId IN (SELECT id FROM users WHERE email LIKE 'seed.%@labonnetablee.test');
DELETE FROM users WHERE email LIKE 'seed.%@labonnetablee.test';

